INSERT IGNORE INTO cmn_policy_resource (policy_code, title, policy_type, description, eligibility, tags, status, publish_date) VALUES
('DG-LB-001', '东莞市最低生活保障政策', 'LOW_INCOME', '对家庭人均收入低于本市最低生活保障标准且家庭财产状况符合规定的家庭，给予基本生活救助。', '1. 具有本市户籍或居住证满1年；2. 家庭月人均收入低于最低生活保障标准；3. 家庭财产状况符合规定。', '低保,救助,困难家庭', 'ACTIVE', '2026-01-01'),
('DG-YL-001', '居家养老服务补贴', 'ELDERLY', '为本市户籍高龄、失能等特殊困难老年人提供居家养老服务和补贴。', '1. 年满80周岁及以上；2. 本市户籍且实际居住；3. 独居或生活困难优先。', '养老,高龄,补贴', 'ACTIVE', '2026-01-15'),
('DG-JZ-001', '临时救助申请指南', 'RESCUE', '对因突发疾病、意外事件等原因导致基本生活暂时陷入困境的家庭，给予临时性救助。', '1. 遭遇突发事件导致基本生活困难；2. 其他社会救助制度暂时无法覆盖；3. 在本市居住生活。', '救助,临时救助,应急', 'ACTIVE', '2026-02-01'),
('DG-YB-001', '城乡居民基本医疗保险参保指南', 'MEDICAL', '城乡居民基本医疗保险参保登记、缴费标准与报销比例说明。', '1. 未参加职工医保的本市户籍居民；2. 在本市居住的港澳台居民；3. 持居住证的非本市户籍人员。', '医保,参保,报销', 'ACTIVE', '2026-02-10'),
('DG-JY-001', '就业困难人员就业扶持政策', 'EMPLOYMENT', '为就业困难人员提供公益性岗位安置、灵活就业社保补贴等就业援助。', '1. 登记失业且难以实现就业的困难人员；2. 零就业家庭成员；3. 大龄失业人员等。', '就业,补贴,援助', 'ACTIVE', '2026-03-01');
